 function finishSession(s:NonNullable<typeof session>){setSession({...s,done:true});setFeedback(null);if(profile&&(s.mode==='mock'||s.mode==='final'||s.mode==='unit-test'))update({...profileRef.current!,tests:[...profileRef.current!.tests,{at:Date.now(),score:s.correct,total:s.answers.length,final:s.mode==='final',...(s.mode==='unit-test'?{unit:profile.currentUnit,previousCount:s.questions.filter(q=>q.unit!==profile.currentUnit).length}:{})}]});}
