 function learnerStart(){if(!profile||!activeWord)return;if(profile.settings.required&&(!attempted||!listened)){toast('Avval so‘zni eshiting va qaytarib ayting.');return;}markSeen(activeWord);setLearnStep(1);setFeedback(null);setAnswer('');startTime.current=Date.now();}
 function fallback(){setAttempted(true);setListened(true);if(profile&&activeWord)update(E.pronounce(profile,activeWord.id,0,true));setSpeechState('Mustaqil takrorlash qayd etildi. Talaffuz balli berilmadi.');}
 async function requestAI(task:string,input:string){const res=await fetch('/api/tutor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({history:messages.slice(-12),task,input,unit:profile?.currentUnit,words:currentWords.map(w=>({word:w.word,meaning:w.meaning,uzbek:w.uzbekMeaning})).slice(0,20)})});const data:any=await res.json();if(!res.ok)throw new Error(data.error||'AI javob bera olmadi.');return data;}
 async function checkWriting(){if(!writing.trim())return;setAiBusy(true);try{const r=await requestAI(view==='speaking'?'speaking':'writing',writing);setWritingFeedback(r.text);}catch(e){toast.error(e instanceof Error?e.message:'Gemini javob bera olmadi.');const fixes:[RegExp,string][]=[[/\bI is\b/gi,'I am'],[/\bShe go\b/gi,'She goes'],[/\bHe go\b/gi,'He goes'],[/\bI have went\b/gi,'I have gone'],[/\bI am agree\b/gi,'I agree'],[/\bcan to\b/gi,'can'],[/\bdid not went\b/gi,'did not go']];const found=fixes.filter(([r])=>r.test(writing));const corrected=fixes.reduce((s,[r,v])=>s.replace(r,v),writing);setWritingFeedback(`Qoidalar asosida dastlabki tekshiruv (Gemini javobi olinmadi).\n\n${writing.trim().split(/\s+/).length} ta so‘z, ${writing.split(/[.!?]+/).filter(s=>s.trim()).length} ta gap.\n${found.length?`Topilgan xatolar: ${found.length}.\nTuzatilgan shakl: ${corrected}`:'Aniq qoidalardagi xato topilmadi. Bu matn to‘liq to‘g‘ri degani emas.'}\n\nAI ulanishi ishlagach grammatika va tabiiylikni to‘liq tekshirish mumkin.`);}finally{setAiBusy(false);}}
 async function tutorSend(){const text=tutorText.trim();if(!text||!profile)return;setTutorText('');setMessages(m=>[...m,{role:'user',text}]);const tq=tutorQuestion.current;if(tq){const ok=E.checkAnswer(tq,text);update(E.answerResult(profile,tq,text,Date.now()-startTime.current));tutorQuestion.current=null;setMessages(m=>[...m,{role:'assistant',text:`${ok?'To‘g‘ri!':'To‘g‘ri javob: '+tq.correctAnswer+'.'} ${tq.explanation}\nKeyingi savol uchun “savol ber” deb yozing.`}]);return;}const n=E.norm(text);if(/savol|so‘ra|so'ra|quiz|test|weak|xato|oldingi/.test(n)){const match=n.match(/unit\s*(\d+)/);const unit=match?Number(match[1]):profile.currentUnit;if(!allUnits.some(u=>u.id===unit)){setMessages(m=>[...m,{role:'assistant',text:'Kitobda Unit 1–30 mavjud.'}]);return;}const mode=/weak|zaif/.test(n)?'weak':/xato/.test(n)?'mistakes':/oldingi/.test(n)?'previous':'current';const ws=mode==='current'?allWords.filter(w=>w.unit===unit):E.pool(profile,mode,allWords);if(!ws.length){setMessages(m=>[...m,{role:'assistant',text:'Bu ro‘yxat hali bo‘sh. Avval so‘zlarni o‘rganing.'}]);return;}const w=E.shuffle(ws)[0],qq=E.makeQuestion(w,/o.zbekchadan|uzbek.*english/.test(n)?'uz-en':'en-uz',allWords);tutorQuestion.current=qq;startTime.current=Date.now();setMessages(m=>[...m,{role:'assistant',text:qq.question}]);return;}if(/grammar|grammatika/.test(n)){const g=grammarTopics.find(g=>n.includes(g.name.toLowerCase()))||grammarTopics[0];setMessages(m=>[...m,{role:'assistant',text:`${g.name}\n${g.rule}\n${g.positive}\n${g.negative}\n${g.question}`}]);return;}if(/talaffuz|pronunciation/.test(n)){go('pronunciation');return;}if(/speaking|gapirish/.test(n)){go('speaking');return;}setAiBusy(true);try{const r=await requestAI('tutor',text);setMessages(m=>[...m,{role:'assistant',text:r.text}]);}catch(e){setMessages(m=>[...m,{role:'assistant',text:'Gemini javobi olinmadi. Sayt egasi AI ulanishini tekshirishi kerak. Hozir kitob so‘zlari va tekshirilgan qoidalar asosidagi tutor ishlaydi. “Savol ber”, “Grammar tushuntir” yoki “Weak words’dan so‘ra” deb yozing.'}]);}finally{setAiBusy(false);}}
 function addDraftWord(){if(!profile||!draftWord.trim()||!draftUz.trim()||!draftMeaning.trim()||!draftExample.trim()){toast.error('Barcha maydonlarni to‘ldiring.');return;}const w:Word={id:editWord?.id||`custom-${Date.now()}`,word:draftWord.trim(),unit:profile.currentUnit,meaning:draftMeaning.trim(),uzbekMeaning:draftUz.trim(),acceptedUzbekMeanings:draftUz.split(';').map(s=>s.trim()),partOfSpeech:editWord?.partOfSpeech||'',phonetic:'',example:draftExample.trim(),sourceType:'extra',verified:false,difficulty:1,page:0,sourceNote:'Kontent'};setProfile({...profile,imports:[...profile.imports.filter(x=>x.id!==w.id),w]});setEditWord(null);setDraftWord('');setDraftUz('');setDraftMeaning('');setDraftExample('');toast('So‘z tekshiruv navbatiga qo‘shildi.');}
 function openEdit(w:Word){setEditWord(w);setDraftWord(w.word);setDraftUz(w.acceptedUzbekMeanings.join(';'));setDraftMeaning(w.meaning);setDraftExample(w.example);}
 async function importFile(file:File){if(file.size>10*1024*1024){setImportInfo('Fayl 10 MB dan kichik bo‘lsin.');return;}setImportInfo('Fayl o‘qilmoqda…');try{let items:any[]=[];const ext=file.name.split('.').pop()?.toLowerCase();if(ext==='json'){const data=JSON.parse(await file.text());if(data.id&&data.wp&&data.settings){if(typeof data.firstName!=='string'||typeof data.lastName!=='string'||!Array.isArray(data.studied)||!Array.isArray(data.mistakes)||!Array.isArray(data.tests)||!data.notes||!Array.isArray(data.imports)||!Array.isArray(data.customQuestions)||!Array.isArray(data.bookmarks)||!Array.isArray(data.studyDays)||!data.grammar||typeof data.answered!=='number'||typeof data.correct!=='number'||!Number.isInteger(data.currentUnit))throw new Error('Progress zaxirasi tuzilishi noto‘g‘ri.');if(!confirm('Zaxiradagi profilni tiklaysizmi?'))return;await writeProfile(E.restoreDefaults(data));localStorage.setItem('essential-active',data.id);update(E.restoreDefaults(data));setImportInfo('Profil va natijalar tiklandi.');return;}items=Array.isArray(data)?data:data.vocabulary||[];}else if(ext==='csv'||ext==='txt'){const lines=(await file.text()).trim().split(/\r?\n/);items=lines.filter(l=>l.includes('\t')||l.includes(',')).map((l,i)=>{const [word,uzbekMeaning,meaning,example]=l.split(l.includes('\t')?'\t':',');return {word,uzbekMeaning,meaning,example};}).filter(x=>x.word.toLowerCase()!=='word');}else{const reader=new FileReader();const base64=await new Promise<string>((res,rej)=>{reader.onload=()=>res(String(reader.result).split(',')[1]);reader.onerror=rej;reader.readAsDataURL(file);});const res=await fetch('/api/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,mime:file.type,base64})});const data:any=await res.json();if(!res.ok)throw new Error(data.error);items=data.vocabulary||[];}
 if(!profile)return;const imported:Word[]=items.filter(x=>typeof x.word==='string'&&typeof x.uzbekMeaning==='string'&&typeof x.meaning==='string'&&typeof x.example==='string').map((x,i)=>({...x,id:x.id||`import-${Date.now()}-${i}`,unit:Number(x.unit)||profile.currentUnit,acceptedUzbekMeanings:x.acceptedUzbekMeanings||[x.uzbekMeaning],partOfSpeech:x.partOfSpeech||'',phonetic:x.phonetic||'',sourceType:'extra',verified:false,difficulty:1,page:0,sourceNote:file.name}));if(!imported.length)throw new Error('Import uchun word, uzbekMeaning, meaning, example maydonlari kerak. JSON yoki CSV shablonini yuklab oling.');update({...profile,imports:[...profile.imports,...imported]});setImportInfo(`${imported.length} ta so‘z tekshiruvga qo‘shildi. Tasdiqlashdan keyin mashqlarga chiqadi.`);}catch(e){setImportInfo(e instanceof Error?e.message:'Faylni o‘qib bo‘lmadi.');}}
 function Quiz(){if(!q)return null;return <section className="quiz-panel card"><div className="row between"><Source book={q.sourceType==='book'}/><span className="muted">{session?`${session.index+1} / ${session.questions.length}`:`${learnStep} / ${learnFormats.length}`} · {q.type}</span></div><Bar value={session?session.index/session.questions.length*100:learnStep/learnFormats.length*100}/>{q.audio&&<button className="audio-pill" onClick={()=>speak(q.audio!)}><Volume2 size={22}/> Eshitish</button>}<h2>{q.question}</h2>{q.speakingText&&<><blockquote className="speak-prompt">{q.speakingText}</blockquote><div className="row"><button type="button" className="btn primary large" disabled={micBusy||!!feedback} onClick={()=>{setAnswer('');record(q.speakingText,undefined,false,true);}}><Mic size={23}/> Ovoz bilan javob berish</button>{micBusy&&<button type="button" className="btn secondary" onClick={stopMic}>Tugatish</button>}</div><p className="muted">Nutq matnga solishtiriladi. Mikrofon ishlamasa pastdagi mikrofonsiz yo‘ldan davom eting.</p>{speechState&&<p role="status">{speechState}</p>}{answer&&<p>Siz aytdingiz: {answer}</p>}</>}{q.type==='order'&&<div className="word-tokens">{E.norm(q.question).split(' / ').map((token,i)=><button key={i} onClick={()=>setAnswer(a=>a+(a?' ':'')+token)} disabled={!!feedback}>{token}</button>)}</div>}<form onSubmit={e=>{e.preventDefault();submit();}}>{q.speakingText?null:q.options?<div className="answer-options">{q.options.map((o,i)=><button type="button" key={o} disabled={!!feedback} onClick={()=>setAnswer(o)} className={answer===o?'chosen':''}><span>{i+1}</span>{o}{answer===o&&<Check size={18}/>}</button>)}</div>:<input className="answer-input" aria-label="Javobingiz" autoComplete="off" autoCapitalize="none" placeholder="Javobingizni yozing…" value={answer} onChange={e=>setAnswer(e.target.value)} disabled={!!feedback}/>}
 {!feedback?<div className="quiz-actions"><button className="btn primary" disabled={!answer.trim()||!!(session?.deadline&&timer===0)} type="submit">Tekshirish</button><button type="button" className="btn ghost" onClick={()=>setHint(h=>h+1)} disabled={session?.mode==='mock'||session?.mode==='final'||session?.mode==='unit-test'||!!q.speakingText}>Yordam {hint>0?hint:''}</button>{q.speakingText&&!feedback&&<button type="button" className="btn ghost" onClick={()=>{stopMic();setAnswer('');setSpeechState('Mustaqil aytish — avtomatik ball berilmadi.');recognitionRef.current=null;setMicBusy(false);if(session){if(session.index+1>=session.questions.length)finishSession(session);else setSession({...session,index:session.index+1});}else setLearnStep(step=>step+1);}}>Mikrofonsiz qaytarib aytdim — ballsiz davom etish</button>}<Pick value={confidence} onChange={setConfidence} items={[["1","Ishonchim kam"],["3","Ishonchim komil"]]}/></div>:<div className={'feedback '+(feedback.ok?'good':'bad')} aria-live="polite"><strong>{feedback.ok?'To‘g‘ri! Yaxshi ishladingiz.':'Qayta eslab qolamiz.'}</strong>{!feedback.ok&&<p>To‘g‘ri javob: <b>{q.correctAnswer}</b></p>}<p>{q.explanation}</p><button type="button" className="btn primary" onClick={nextQuestion}>Davom etish</button></div>}
 {hint>0&&!feedback&&session?.mode!=='mock'&&session?.mode!=='final'&&session?.mode!=='unit-test'&&<p className="hint">{hint===1?`Birinchi belgi: ${q.correctAnswer[0]}.`:hint===2?`${q.correctAnswer.length} ta belgi. ${q.topic?grammarTopics.find(g=>g.id===q.topic)?.rule:'So‘zning o‘rganilgan ma’nosini eslang.'}`:hint===3?q.explanation:`Javob: ${q.correctAnswer}`}</p>}</form></section>;}
 if(!loaded)return <div className="welcome"><div className="brand-mark"><BookOpen/></div><h1>ESSENTIAL MASTERY</h1><p>O‘quv maydoningiz ochilmoqda…</p></div>;
 if(!profile)return <main className="welcome"><div className="welcome-brand"><div className="brand-mark"><BookOpen size={29}/></div><span>ESSENTIAL<br/><b>MASTERY</b></span></div><div className="welcome-card"><span className="eyebrow">SIZNING INGLIZ TILI MAYDONINGIZ</span><h1>O‘rganing.<br/><em>Esda qoldiring.</em></h1><p>600 so‘z. 30 Unit. Har kuni bir qadam oldinga.</p><form onSubmit={login}><label>Ismingiz<input value={fn} onChange={e=>setFn(e.target.value)} required autoComplete="given-name" placeholder="Ismingiz" maxLength={60}/></label><label>Familiyangiz<input value={ln} onChange={e=>setLn(e.target.value)} required autoComplete="family-name" placeholder="Familiyangiz" maxLength={60}/></label><button className="btn primary large" type="submit">Boshlash</button></form><small>Profilingiz va natijalar shu qurilmada saqlanadi.</small>{savingError&&<p className="error">{savingError}</p>}</div><div className="welcome-footer">4000 Essential English Words 1 · Paul Nation</div><Toaster/></main>;
 const unit=allUnits.find(u=>u.id===profile.currentUnit)!;const mastered=allWords.filter(w=>E.isMastered(profile.wp[w.id])).length;const activeMistakes=profile.mistakes.filter(m=>!m.resolved);
 const listWords=view==='weak'?weak:view==='weakpron'?allWords.filter(w=>profile.wp[w.id]?.seen&&!profile.wp[w.id]?.pronunciation.completed):allWords;
 const filteredWords=listWords.filter(w=>!search||E.norm(w.word+' '+w.uzbekMeaning+' '+w.unit).includes(E.norm(search))).slice(0,80);
